/* 0085_the_customers_own_reference.sql, flattened for the Supabase SQL editor. Generated by scripts/flatten-migration.mjs - do not edit this file, edit the migration and run the script again. One statement per line, no line comments, nothing to lose to a newline. The commentary lives in the migration itself. */
alter table public.orders add column if not exists customer_reference text check ( customer_reference is null or (length(customer_reference) between 1 and 120 and customer_reference = btrim(customer_reference)) );
comment on column public.orders.customer_reference is 'The customer''s own label for this order - a name, a client, a PO number. Not unique, not ours, never parsed. Null means nobody labelled it.';
create index if not exists orders_customer_reference_idx on public.orders (user_id, lower(customer_reference)) where customer_reference is not null;
create or replace function public.admin_order_page( p_search text default null, p_status text default null, p_limit integer default 50, p_offset integer default 0 ) returns table (id uuid, total bigint) language sql stable security definer set search_path = public as $$ with matched as ( select o.id, o.placed_at from public.orders o join public.profiles p on p.id = o.user_id where (p_status is null or p_status = 'all' or o.status::text = p_status) and ( coalesce(btrim(p_search), '') = '' or position( lower(btrim(p_search)) in lower(o.reference || ' ' || coalesce(p.full_name, '') || ' ' || coalesce(p.email, '') || ' ' || coalesce(o.customer_reference, '')) ) > 0 or exists ( select 1 from public.order_items oi where oi.order_id = o.id and position(lower(btrim(p_search)) in lower(oi.website_domain)) > 0 ) ) ) select matched.id, count(*) over () as total from matched order by matched.placed_at desc, matched.id asc limit greatest(1, least(coalesce(p_limit, 50), 250)) offset greatest(0, coalesce(p_offset, 0)); $$;
comment on function public.admin_order_page(text, text, integer, integer) is 'One page of the admin order table. Returns ids and the total; the caller maps the rows with the select it already has. Searches our reference, the customer''s name and email, the customer''s own reference, and any placement''s domain.';
revoke all on function public.admin_order_page(text, text, integer, integer) from public;
revoke all on function public.admin_order_page(text, text, integer, integer) from anon;
revoke all on function public.admin_order_page(text, text, integer, integer) from authenticated;
